const feedback=document.querySelector('#copy-feedback');const timers=new WeakMap();async function copyText(text,button){const idle=button.hasAttribute('data-copy-all')?'Copy reported codes':'Copy';clearTimeout(timers.get(button));try{if(!navigator.clipboard?.writeText)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(text);feedback.textContent=button.hasAttribute('data-copy-all')?'Reported codes copied. Their verification status has not changed.':text+' copied.';button.textContent='Copied';timers.set(button,setTimeout(()=>button.textContent=idle,1800));}catch{button.textContent=idle;feedback.textContent='Copy was blocked by your browser. Select the complete code and copy it manually.';}}document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',()=>copyText(button.dataset.copy,button)));document.querySelector('[data-copy-all]')?.addEventListener('click',event=>copyText([...document.querySelectorAll('#reported-codes [data-copy]')].map(button=>button.dataset.copy).join(String.fromCharCode(10)),event.currentTarget));